INSERT INTO propertymetadata VALUES(3,'elements','atomic_number','Element','atomic_number','basic properties','STORED','Atomic number',NULL,NULL,NULL);
INSERT INTO propertymetadata VALUES(4,'elements','atomic_radius','Element','atomic_radius','atomic size properties','STORED','Atomic radius','pm',NULL,'Slater1964');
INSERT INTO propertymetadata VALUES(5,'elements','atomic_radius_rahm','Element','atomic_radius_rahm','atomic size properties','STORED','Atomic radius by Rahm et al.','pm',NULL,'Rahm2016,Rahm2017');
INSERT INTO propertymetadata VALUES(6,'elements','atomic_volume','Element','atomic_volume','atomic size properties','COMPUTED','Atomic volume','cm^3/mol',NULL,NULL);
INSERT INTO propertymetadata VALUES(7,'elements','atomic_weight','Element','atomic_weight','basic properties','STORED','Relative atomic weight','Da','Atomic weights and their uncertainties were retrieved mainly from ref. :cite:`iupac-weights`. For elements whose values were given as ranges the *conventional atomic weights* from Table 3 in ref. :cite:`Meija2016` were taken. For radioactive elements the standard approach was adopted where the weight is taken as the mass number of the most stable isotope. The data was obtained from `CIAAW page on radioactive elements <http://www.ciaaw.org/radioactive-elements.htm>`_. In cases where two isotopes were specified the one with the smaller standard deviation was chosen. In case of Tc and Pm relative weights of their isotopes were used, for Tc isotope 98, and for Pm isotope 145 were taken from `CIAAW <http://www.ciaaw.org/atomic-masses.htm>`_.','Meija2016,iupac-weights');
INSERT INTO propertymetadata VALUES(8,'elements','atomic_weight_uncertainty','Element','atomic_weight_uncertainty','basic properties','STORED','Atomic weight uncertainty','Da',NULL,'Meija2016,iupac-weights');
INSERT INTO propertymetadata VALUES(9,'elements','block','Element','block','periodic table properties','STORED','Block in periodic table',NULL,NULL,NULL);
INSERT INTO propertymetadata VALUES(10,'elements','c6','Element','c6','electric and optical properties','STORED','C_6 dispersion coefficient','hartree/bohr^6',NULL,'Chu2004,Tang1976');
INSERT INTO propertymetadata VALUES(11,'elements','c6_gb','Element','c6_gb','electric and optical properties','STORED','C_6 dispersion coefficient according to Gould & Bučko','hartree/bohr^6',NULL,'Gould2016');
