INSERT INTO propertymetadata VALUES(14,'elements','covalent_radius_cordero','Element','covalent_radius_cordero','atomic size properties','STORED','Covalent radius by Cerdero et al.','pm','In order to have a more homogeneous data for covalent radii taken from ref. :cite:`Cordero2008` the values for 3 different valences for C, also the low and high spin values for Mn, Fe Co, were respectively averaged.','Cordero2008');
INSERT INTO propertymetadata VALUES(15,'elements','covalent_radius_pyykko','Element','covalent_radius_pyykko','atomic size properties','STORED','Single bond covalent radius by Pyykko et al.','pm',NULL,'Pyykko2009');
INSERT INTO propertymetadata VALUES(16,'elements','covalent_radius_pyykko_double','Element','covalent_radius_pyykko_double','atomic size properties','STORED','Double bond covalent radius by Pyykko et al.','pm',NULL,'Pyykko2009a');
