INSERT INTO propertymetadata VALUES(172,'elements','en_gunnarsson_lundqvist','Element','en_gunnarsson_lundqvist','chemical properties','STORED','Gunnarsson-Lundqvist''s scale of electronegativity','eV',NULL,'GunnarssonLundqvist1979,RoblesBartolotti1984');
INSERT INTO propertymetadata VALUES(173,'elements','political_stability_of_top_producer','Element','political_stability_of_top_producer','supply risk properties','STORED','A percentile rank for the political stability of the top producing country, derived from World Bank governance indicators.',NULL,NULL,'RSC_periodic_table');
INSERT INTO propertymetadata VALUES(174,'elements','political_stability_of_top_reserve_holder','Element','political_stability_of_top_reserve_holder','supply risk properties','STORED','A percentile rank for the political stability of the country with the largest reserves, derived from World Bank governance indicators.',NULL,NULL,'RSC_periodic_table');
INSERT INTO propertymetadata VALUES(175,'elements','production_concentration','Element','production_concentration','supply risk properties','STORED','The percentage of an element produced in the top producing country. The higher the value, the larger risk there is to supply.','%',NULL,'RSC_periodic_table');
INSERT INTO propertymetadata VALUES(176,'elements','recycling_rate','Element','recycling_rate','supply risk properties','STORED','The percentage of a commodity which is recycled. A higher recycling rate may reduce risk to supply.','%',NULL,'RSC_periodic_table');
INSERT INTO propertymetadata VALUES(177,'elements','relative_supply_risk','Element','relative_supply_risk','supply risk properties','STORED','An integrated supply risk index from 1 (very low risk) to 10 (very high risk). This is calculated by combining the scores for crustal abundance, reserve distribution, production concentration, substitutability, recycling rate and political stability scores.',NULL,NULL,'RSC_periodic_table');
INSERT INTO propertymetadata VALUES(178,'elements','reserve_distribution','Element','reserve_distribution','supply risk properties','STORED','The percentage of the world reserves located in the country with the largest reserves. The higher the value, the larger risk there is to supply.','%',NULL,'RSC_periodic_table');
INSERT INTO propertymetadata VALUES(179,'elements','substitutability','Element','substitutability','supply risk properties','STORED','The availability of suitable substitutes for a given commodity. High - substitution not possible or very difficult, medium - substitution is possible but there may be an economic and/or performance impact, low = substitution is possible with little or no economic and/or performance impact',NULL,NULL,'RSC_periodic_table');
INSERT INTO propertymetadata VALUES(180,'elements','top_3_producers','Element','top_3_producers','supply risk properties','STORED','Top 3 countries or regions that produce the element.',NULL,NULL,'RSC_periodic_table');
INSERT INTO propertymetadata VALUES(181,'elements','top_3_reserve_holders','Element','top_3_reserve_holders','supply risk properties','STORED','Top 3 countries or regions that hold reserves the element.',NULL,NULL,'RSC_periodic_table');
INSERT INTO propertymetadata VALUES(182,'phasetransitions','is_sublimation_point','PhaseTransition','is_sublimation_point','annotation flag','STORED','Indicates that boiling_point marks a sublimation point, where the vapor pressure of the solid phase reaches 101.325 kPa (1 atm)',NULL,NULL,'haynes2016crc');
INSERT INTO propertymetadata VALUES(183,'phasetransitions','is_transition','PhaseTransition','is_transition','annotation flag','STORED','Indicates that melting_point marks the temperature of the transition to the crystalline form immediately below that entry',NULL,NULL,'haynes2016crc');
INSERT INTO propertymetadata VALUES(184,'elements','price_per_kg','Element','price_per_kg','monetary','STORED','Price per kg in USD','USD/kg','In cases where a range was provided in the source, the lower value was used. In cases of multiple isotopes the lower priced isotope''s price was used.','enwiki:1262554464');
INSERT INTO propertymetadata VALUES(185,'elements','en_mullay','Element','en_mullay','chemical properties','STORED','Mullay''s scale of electronegativity',NULL,replace('In the original paper multiple values of electronegativity are provided for several elements. The values corresponding to following hybrids were chosen:\n\n- C *sp3*\n- N *p*\n- O *p*\n- F *p*\n- CL *p*\n- Br *p*\n- I *p*','\n',char(10)),'mullay1984atomic');
