PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE series (
	id INTEGER NOT NULL, 
	name VARCHAR, color VARCHAR, 
	PRIMARY KEY (id)
);
CREATE TABLE groups (
	group_id INTEGER NOT NULL, 
	symbol VARCHAR, 
	name VARCHAR, 
	PRIMARY KEY (group_id)
);
CREATE TABLE oxidationstates (
	id INTEGER NOT NULL, 
	atomic_number INTEGER, 
	oxidation_state INTEGER, category VARCHAR, 
	PRIMARY KEY (id), 
	FOREIGN KEY(atomic_number) REFERENCES elements (atomic_number)
);
CREATE TABLE ionicradii (
	id INTEGER NOT NULL, 
	atomic_number INTEGER, 
	charge INTEGER, 
	econf VARCHAR, 
	coordination VARCHAR, 
	spin VARCHAR, 
	crystal_radius FLOAT, 
	ionic_radius FLOAT, 
	origin VARCHAR, 
	most_reliable BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(atomic_number) REFERENCES elements (atomic_number), 
	CHECK (most_reliable IN (0, 1))
);
CREATE TABLE screeningconstants (
	id INTEGER NOT NULL, 
	atomic_number INTEGER, 
	n INTEGER, 
	s VARCHAR, 
	screening FLOAT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(atomic_number) REFERENCES elements (atomic_number)
);
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL
);
CREATE TABLE IF NOT EXISTS "isotopes" (
	id INTEGER NOT NULL, 
	atomic_number INTEGER, 
	mass FLOAT, 
	abundance FLOAT, 
	mass_number INTEGER, 
	mass_uncertainty FLOAT, 
	is_radioactive BOOLEAN, 
	half_life FLOAT, 
	half_life_unit VARCHAR, 
	spin VARCHAR, 
	g_factor FLOAT, 
	quadrupole_moment FLOAT, 
	parity VARCHAR, 
	discovery_year INTEGER, 
	g_factor_uncertainty FLOAT, 
	abundance_uncertainty FLOAT, 
	half_life_uncertainty FLOAT, 
	quadrupole_moment_uncertainty FLOAT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(atomic_number) REFERENCES elements (atomic_number)
);
CREATE TABLE isotopedecaymodes (
	id INTEGER NOT NULL, 
	isotope_id INTEGER NOT NULL, 
	mode VARCHAR(10) NOT NULL, 
	relation VARCHAR(1), 
	intensity FLOAT, 
	is_allowed_not_observed BOOLEAN, 
	is_observed_intensity_unknown BOOLEAN, 
	PRIMARY KEY (id), 
	CONSTRAINT fk_isotope_decaymodes_1 FOREIGN KEY(isotope_id) REFERENCES isotopes (id) ON DELETE CASCADE
);
CREATE TABLE propertymetadata (
	id INTEGER NOT NULL, 
	table_name VARCHAR, 
	column_name VARCHAR, 
	class_name VARCHAR NOT NULL, 
	attribute_name VARCHAR NOT NULL, 
	category VARCHAR NOT NULL, 
	value_origin VARCHAR(8) NOT NULL, 
	description TEXT NOT NULL, 
	unit VARCHAR, 
	annotations TEXT, 
	citation_keys VARCHAR, 
	PRIMARY KEY (id)
);
CREATE TABLE scattering_factors (
	id INTEGER NOT NULL, 
	atomic_number INTEGER, 
	energy FLOAT, 
	f1 FLOAT, 
	f2 FLOAT, 
	PRIMARY KEY (id)
);
CREATE TABLE ionizationenergies (
	id INTEGER NOT NULL, 
	atomic_number INTEGER NOT NULL, 
	species_name VARCHAR NOT NULL, 
	ion_charge INTEGER NOT NULL, 
	isoelectonic_sequence VARCHAR NOT NULL, 
	ground_shells VARCHAR, 
	ground_configuration VARCHAR, 
	ground_level VARCHAR, 
	ionized_level VARCHAR, 
	ionization_energy FLOAT, 
	uncertainty FLOAT, 
	"references" TEXT, 
	is_semi_empirical BOOLEAN, 
	is_theoretical BOOLEAN, 
	PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS "phasetransitions" (
	id INTEGER NOT NULL, 
	atomic_number INTEGER, 
	boiling_point FLOAT, 
	melting_point FLOAT, 
	critical_temperature FLOAT, 
	critical_pressure FLOAT, 
	triple_point_temperature FLOAT, 
	triple_point_pressure FLOAT, 
	allotrope VARCHAR(50), is_sublimation_point BOOLEAN, is_transition BOOLEAN, 
	PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS "elements" (
	atomic_number INTEGER NOT NULL, 
	atomic_radius FLOAT, 
	block VARCHAR, 
	density FLOAT, 
	description VARCHAR, 
	dipole_polarizability FLOAT, 
	electron_affinity FLOAT, 
	electronic_configuration VARCHAR, 
	evaporation_heat FLOAT, 
	fusion_heat FLOAT, 
	group_id INTEGER, 
	lattice_constant FLOAT, 
	lattice_structure VARCHAR, 
	name VARCHAR, 
	period INTEGER, 
	series_id INTEGER, 
	specific_heat_capacity FLOAT, 
	symbol VARCHAR, 
	thermal_conductivity FLOAT, 
	vdw_radius FLOAT, 
	covalent_radius_cordero FLOAT, 
	covalent_radius_pyykko FLOAT, 
	en_pauling FLOAT, 
	en_allen FLOAT, 
	jmol_color VARCHAR, 
	cpk_color VARCHAR, 
	proton_affinity FLOAT, 
	gas_basicity FLOAT, 
	heat_of_formation FLOAT, 
	c6 FLOAT, 
	covalent_radius_bragg FLOAT, 
	vdw_radius_bondi FLOAT, 
	vdw_radius_truhlar FLOAT, 
	vdw_radius_rt FLOAT, 
	vdw_radius_batsanov FLOAT, 
	vdw_radius_dreiding FLOAT, 
	vdw_radius_uff FLOAT, 
	vdw_radius_mm3 FLOAT, 
	abundance_crust FLOAT, 
	abundance_sea FLOAT, 
	molcas_gv_color VARCHAR, 
	en_ghosh FLOAT, 
	vdw_radius_alvarez FLOAT, 
	c6_gb FLOAT, 
	atomic_weight FLOAT, 
	atomic_weight_uncertainty FLOAT, 
	is_monoisotopic BOOLEAN, 
	is_radioactive BOOLEAN, 
	cas VARCHAR, 
	atomic_radius_rahm FLOAT, 
	geochemical_class VARCHAR, 
	goldschmidt_class VARCHAR, 
	metallic_radius FLOAT, 
	metallic_radius_c12 FLOAT, 
	covalent_radius_pyykko_double FLOAT, 
	covalent_radius_pyykko_triple FLOAT, 
	discoverers VARCHAR, 
	discovery_year INTEGER, 
	discovery_location VARCHAR, 
	name_origin VARCHAR, 
	sources VARCHAR, 
	uses VARCHAR, 
	mendeleev_number INTEGER, 
	dipole_polarizability_unc FLOAT, 
	pettifor_number INTEGER, 
	glawe_number INTEGER, 
	molar_heat_capacity FLOAT, 
	en_miedema FLOAT, 
	miedema_molar_volume FLOAT, 
	miedema_electron_density FLOAT, 
	en_gunnarsson_lundqvist FLOAT, 
	en_robles_bartolotti FLOAT, 
	production_concentration FLOAT, 
	relative_supply_risk FLOAT, 
	reserve_distribution FLOAT, 
	political_stability_of_top_producer FLOAT, 
	political_stability_of_top_reserve_holder FLOAT, 
	top_3_producers VARCHAR, 
	top_3_reserve_holders VARCHAR, 
	recycling_rate VARCHAR, 
	substitutability VARCHAR, 
	price_per_kg FLOAT, en_mullay FLOAT, 
	PRIMARY KEY (atomic_number), 
	FOREIGN KEY(group_id) REFERENCES groups (group_id), 
	FOREIGN KEY(series_id) REFERENCES series (id)
);
COMMIT;
